            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
def _stark_should_pad_matmul(A, B):
    return (
        A.is_cuda and B.is_cuda and
        A.dtype == torch.float32 and B.dtype == torch.float32 and
        A.dim() == 2 and B.dim() == 2 and
        A.shape[0] == A.shape[1] and
        B.shape[0] == B.shape[1] and
        A.shape[0] == B.shape[0] and
        A.is_contiguous() and B.is_contiguous() and
        A.shape[0] >= 256 and
        A.shape[0] % 16 != 0
    )

def _stark_pad_square_to_multiple(x, multiple):
    n = x.shape[0]
    padded_n = ((n + multiple - 1) // multiple) * multiple
    if padded_n == n:
        return x, n
    padded = torch.zeros(padded_n, padded_n, dtype=x.dtype, device=x.device)
    padded[:n, :n].copy_(x)
    return padded, n
# <<<END_IMPROVE>>>

