struct ShapeKey {
    int64_t M, N, K;
    bool operator==(const ShapeKey& o) const {
        return M==o.M && N==o.N && K==o.K;
    }
};
struct ShapeKeyHash {
    size_t operator()(const ShapeKey& k) const {
        size_t h = std::hash<int64_t>{}(k.M);
        h ^= std::hash<int64_t>{}(k.N) + 0x9e3779b9 + (h<<6) + (h>>2);
        h ^= std::hash<int64_t>{}(k.K) + 0x9e3779b9 + (h<<6) + (h>>2);
        return h;
    }
};

// Per-device cached cuBLAS handle state
struct DeviceState {
    cublasHandle_t handle = nullptr;
};

static std::mutex g_mutex;
static std::unordered_map<int, DeviceState> g_states;

static DeviceState& get_state(int device_idx) {
    std::lock_guard<std::mutex> lock(g_mutex);
    auto& state = g_states[device_idx];
    if (state.handle == nullptr) {
        cublasCreate(&state.handle);
    }
    return state;
}

torch::Tensor symmetric_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "Inputs must be contiguous");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    int64_t N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    int device_idx = A.device().index();
    c10::cuda::CUDAGuard device_guard(A.device());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    float alpha = 1.0f;
    float beta  = 0.0f;

    bool used_symm = false;

    // Try cublasSsymm for square symmetric matrices
    // cuBLAS is column-major. For row-major A(M,K) and B(K,N):
    // We want C = A * B in row-major.
    // In column-major: C^T = B^T * A^T
    // If A is symmetric (A^T = A) and square (M==K), we can use Ssymm:
    // cublasSsymm(side=RIGHT, uplo=UPPER, m=N, n=M, alpha, A, lda, B^T, ldb, beta, C^T, ldc)
    // But B^T is not contiguous. Alternative:
    // If B is symmetric (B^T = B) and square (K==N), use Ssymm with side=LEFT:
    // C^T = B * A^T  => cublasSsymm(side=LEFT, uplo=UPPER, m=N, n=M, alpha, B, ldb, A, lda, beta, C^T, ldc)
    // This computes C^T = B * A^T = B * A (since A symmetric) = (A*B)^T => C = A*B. Correct!
    if (M == K && K == N) {
        // Both A and B are square and symmetric
        // Use cublasSsymm: C^T = B * A^T = B * A (A symmetric)
        // In col-major: C_col(N,M) = B_col(N,N) * A_col(N,M)
        // side=LEFT means symmetric matrix is on the left
        // m = number of rows of C_col = N, n = number of cols of C_col = M
        DeviceState& state = get_state(device_idx);
        cublasSetStream(state.handle, stream);
        cublasStatus_t status = cublasSsymm(
            state.handle,
            CUBLAS_SIDE_LEFT,
            CUBLAS_FILL_MODE_UPPER,
            (int)N,   // m: rows of C_col
            (int)M,   // n: cols of C_col
            &alpha,
            B.data_ptr<float>(), (int)B.stride(0),  // symmetric matrix B, ldb
            A.data_ptr<float>(), (int)A.stride(0),  // general matrix A, lda
            &beta,
            C.data_ptr<float>(), (int)C.stride(0)   // output C, ldc
        );
        if (status == CUBLAS_STATUS_SUCCESS) {
            used_symm = true;
        }
    }

    if (!used_symm) {
        // Generic cublasSgemm fallback (column-major trick: C = A*B row-major => C^T = B^T * A^T col-major)
        cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
        cublasSetStream(handle, stream);
        cublasStatus_t status = cublasSgemm(
            handle,
            CUBLAS_OP_N, CUBLAS_OP_N,
            (int)N, (int)M, (int)K,
            &alpha,
            B.data_ptr<float>(), (int)B.stride(0),
            A.data_ptr<float>(), (int)A.stride(0),
            &beta,
            C.data_ptr<float>(), (int)C.stride(0)
        );
        TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasSgemm fallback failed");
    }

    return C;
}
